import re

_JOB_PATTERN = re.compile(
    r"^JOB\s+(?P<name>\S+)\s+AT\s+(?P<at>(?:[01]\d|2[0-3]):[0-5]\d)"
    r"\s+RUN\s+(?P<script>\S+\.crms)"
    r"(?:\s+ON_ERROR\s+(?P<error>ABORT|CONTINUE|RETRY:\d+))?\s*$"
)


def parse_schedule(cfg_text: str) -> list[dict]:
    """Parse Meridian CRM batch_jobs.cfg text into the target schedule schema."""
    schedule: list[dict] = []

    for line_number, line in enumerate(cfg_text.splitlines(), start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        match = _JOB_PATTERN.fullmatch(stripped)
        if match is None:
            raise ValueError(f"Invalid batch job definition on line {line_number}")

        error_clause = match.group("error") or "ABORT"
        if error_clause.startswith("RETRY:"):
            on_error = {
                "policy": "RETRY",
                "retries": int(error_clause.split(":", 1)[1]),
            }
        else:
            on_error = {"policy": error_clause, "retries": 0}

        schedule.append(
            {
                "name": match.group("name"),
                "at": match.group("at"),
                "script": match.group("script"),
                "on_error": on_error,
            }
        )

    return schedule
